 public class DesktopData { public int version{get;set;} public List<DeskGroup> groups{get;set;} public DesktopData(){version=1;groups=new List<DeskGroup>();} }
 public class DeskGroup {public string id{get;set;} public string title{get;set;} public string subtitle{get;set;} public List<DeskItem> items{get;set;} public int desktopX{get;set;} public int desktopY{get;set;} public DeskGroup(){items=new List<DeskItem>();desktopX=-1;desktopY=-1;} }
 public class DeskItem {public string id{get;set;} public string title{get;set;} public string description{get;set;} public string type{get;set;} public string target{get;set;} public string icon{get;set;} public string arguments{get;set;} }
 public class DesktopStore {
  public string Root{get;private set;} public DesktopData Data{get;private set;} string original; readonly object gate=new object();
  static JavaScriptSerializer Serializer(){return new JavaScriptSerializer{MaxJsonLength=int.MaxValue,RecursionLimit=256};}
  static string Hash(byte[] b){using(var h=SHA256.Create())return Convert.ToBase64String(h.ComputeHash(b));}
  public DesktopStore(string root){Root=NormalizeRoot(root);Reload();}
  static string NormalizeRoot(string root){string full=Path.GetFullPath(root).Replace('/','\\');string volume=Path.GetPathRoot(full);return full.Length==volume.Length?full:full.TrimEnd('\\');}
  // Cooperating DesktopStore writers share this mutex. Hash checking is NOT an
  // atomic CAS against arbitrary external editors which ignore this protocol.
  IDisposable AcquireWriteLock(){string identity=Root.TrimEnd('\\').ToUpperInvariant();string name="Local\\MacDeskNative.Store."+Hash(Encoding.UTF8.GetBytes(identity)).Replace('/','_').Replace('+','-').TrimEnd('=');return new WriterLock(name);}
  sealed class WriterLock:IDisposable {Mutex mutex;bool held;public WriterLock(string name){mutex=new Mutex(false,name);try{try{held=mutex.WaitOne(30000);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("其他MacDesk进程正在保存，请稍后重试。");}catch{mutex.Dispose();throw;}}public void Dispose(){try{if(held)mutex.ReleaseMutex();}finally{mutex.Dispose();}}}
  public static string NewId(){return "G"+Guid.NewGuid().ToString("N");}
  public void Reload(){lock(gate){string path=Path.Combine(Root,"desktop.json");byte[] b=File.Exists(path)?File.ReadAllBytes(path):null;DesktopData next=b==null?new DesktopData():Serializer().Deserialize<DesktopData>(Encoding.UTF8.GetString(b).TrimStart('﻿'));Validate(next);Data=next;original=b==null?null:Hash(b);}}
  public static void Validate(DesktopData d){if(d==null||d.version!=1||d.groups==null)throw new InvalidDataException("不支持的桌面数据版本或格式。");var ids=new HashSet<string>(StringComparer.Ordinal);foreach(var g in d.groups){if(g==null)throw new InvalidDataException("分类为空。");CheckId(g.id,ids);if(g.desktopX < -1 || g.desktopY < -1 || g.desktopX > 32767 || g.desktopY > 32767 || ((g.desktopX==-1)!=(g.desktopY==-1)))throw new InvalidDataException("文件夹位置无效。");if(String.IsNullOrWhiteSpace(g.title)||g.items==null)throw new InvalidDataException("分类名称或条目列表无效。");foreach(var i in g.items){if(i==null)throw new InvalidDataException("条目为空。");CheckId(i.id,ids);if(String.IsNullOrWhiteSpace(i.title))throw new InvalidDataException("条目名称不能为空。");EntryServices.ValidateTarget(i.type,i.target,false);if(!String.IsNullOrEmpty(i.icon)&&!Path.IsPathRooted(i.icon))throw new InvalidDataException("图标必须是完整路径。");if(i.arguments!=null&&i.arguments.IndexOf('\0')>=0)throw new InvalidDataException("启动参数包含无效字符。");}}}
  static void CheckId(string id,HashSet<string> ids){if(id==null||!Regex.IsMatch(id,@"\A[A-Za-z0-9_-]+\z")||!ids.Add(id))throw new InvalidDataException("ID无效或重复。");}
  public void Edit(Action<DesktopData> mutation){if(mutation==null)throw new ArgumentNullException("mutation");lock(gate){using(var writeLock=AcquireWriteLock()){var s=Serializer();var next=s.Deserialize<DesktopData>(s.Serialize(Data));mutation(next);Validate(next);byte[] bytes=new UTF8Encoding(false).GetBytes(s.Serialize(next));Directory.CreateDirectory(Root);string path=Path.Combine(Root,"desktop.json"),temp=Path.Combine(Root,".desktop-"+Guid.NewGuid().ToString("N")+".tmp");try{using(var f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){f.Write(bytes,0,bytes.Length);f.Flush(true);}if(File.Exists(path)){using(var current=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read|FileShare.Delete)){byte[] old;using(var ms=new MemoryStream()){current.CopyTo(ms);old=ms.ToArray();}if(original==null||Hash(old)!=original)throw new IOException("配置已被其他程序更新，请重新加载后重试。");string backups=Path.Combine(Root,"Backups");Directory.CreateDirectory(backups);string backup=Path.Combine(backups,"data-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fffffff")+"-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllBytes(backup,old);File.Replace(temp,path,null);}}else{if(original!=null)throw new IOException("原配置已被删除，请重新加载。");File.Move(temp,path);}Data=next;original=Hash(bytes);}finally{if(File.Exists(temp))File.Delete(temp);}}}}
 }
 public static class EntryServices {
  static readonly Dictionary<string,Image> cache=new Dictionary<string,Image>(StringComparer.OrdinalIgnoreCase);static readonly object gate=new object();
  public static string ValidateTarget(string type,string target,bool exists){if(String.IsNullOrWhiteSpace(target)||target.IndexOfAny(new char[]{'\0','\r','\n'})>=0)throw new InvalidDataException("目标不能为空或包含控制字符。");if(type=="url"){Uri u;if(!Uri.TryCreate(target,UriKind.Absolute,out u)||(u.Scheme!="http"&&u.Scheme!="https"))throw new InvalidDataException("只支持完整http/https网址。");return u.AbsoluteUri;}if(type!="app"&&type!="file"&&type!="folder")throw new InvalidDataException("不支持的入口类型。");if(!IsAbsolutePath(target))throw new InvalidDataException("目标必须是绝对路径，例如 C:\\Apps\\App.exe 或 \\\\server\\share\\file；不支持驱动器相对或根相对路径。");string full=Path.GetFullPath(target);if(exists&&(type=="folder"?!Directory.Exists(full):!File.Exists(full)))throw new FileNotFoundException("目标已不存在，请编辑入口更新路径。",full);return full;}
  public static bool IsAbsolutePath(string path){if(String.IsNullOrWhiteSpace(path))return false;string p=path.Replace('/','\\');if(Regex.IsMatch(p,@"\A[A-Za-z]:\\"))return true;if(!p.StartsWith(@"\\",StringComparison.Ordinal))return false;string[] parts=p.Substring(2).Split('\\');return parts.Length>=2&&!String.IsNullOrWhiteSpace(parts[0])&&!String.IsNullOrWhiteSpace(parts[1])&&parts[0]!="?"&&parts[0]!="."&&parts[1]!="."&&parts[1]!="..";}
  public static DeskItem FromPath(string path){string full=ValidateTarget("file",path,false);bool folder=Directory.Exists(full);if(!folder&&!File.Exists(full))throw new FileNotFoundException("文件或文件夹不存在。",full);string ext=Path.GetExtension(full);string title=Path.GetFileName(full.TrimEnd(Path.DirectorySeparatorChar));if(String.IsNullOrEmpty(title))title=full;return new DeskItem{id=DesktopStore.NewId(),title=title,description="",type=folder?"folder":(ext.Equals(".exe",StringComparison.OrdinalIgnoreCase)||ext.Equals(".lnk",StringComparison.OrdinalIgnoreCase)?"app":"file"),target=full,icon="",arguments=""};}
  public static DeskItem FromUrl(string url){string full=ValidateTarget("url",url,false);var u=new Uri(full);return new DeskItem{id=DesktopStore.NewId(),title=u.Host,description="",type="url",target=full,icon="",arguments=""};}
  public static void Open(DeskItem item){if(item==null)throw new ArgumentNullException("item");string target=ValidateTarget(item.type,item.target,true);object shell=null,windows=null,desktop=null,document=null,application=null;try{shell=Activator.CreateInstance(Type.GetTypeFromProgID("Shell.Application"));dynamic sh=shell;windows=sh.Windows();dynamic ws=windows;int hwnd=0;desktop=ws.FindWindowSW(0,0,8,out hwnd,1);if(desktop==null)throw new InvalidOperationException("Explorer桌面暂时不可用。");dynamic desk=desktop;document=desk.Document;dynamic doc=document;application=doc.Application;dynamic app=application;app.ShellExecute(target,item.type=="app"?(item.arguments??""):"",item.type=="url"?"":Path.GetDirectoryName(target),"open",1);}finally{Release(application);Release(document);Release(desktop);Release(windows);Release(shell);}}
  static void Release(object o){if(o!=null&&Marshal.IsComObject(o))Marshal.ReleaseComObject(o);}
  [StructLayout(LayoutKind.Sequential)] struct SIZE {public int cx,cy;public SIZE(int x,int y){cx=x;cy=y;}}
  [ComImport,Guid("bcc18b79-ba16-442f-80c4-8a59c30c463b"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface IShellItemImageFactory{[PreserveSig]int GetImage(SIZE size,int flags,out IntPtr bitmap);}
  [DllImport("shell32.dll",CharSet=CharSet.Unicode,PreserveSig=true)] static extern int SHCreateItemFromParsingName(string path,IntPtr context,ref Guid iid,[MarshalAs(UnmanagedType.Interface)]out IShellItemImageFactory factory);
  [DllImport("gdi32.dll")]static extern bool DeleteObject(IntPtr handle);
  static Image ShellIcon(string path){IShellItemImageFactory factory=null;IntPtr h=IntPtr.Zero;try{Guid id=typeof(IShellItemImageFactory).GUID;if(SHCreateItemFromParsingName(path,IntPtr.Zero,ref id,out factory)!=0||factory==null)return null;if(factory.GetImage(new SIZE(96,96),1|4,out h)!=0||h==IntPtr.Zero)return null;using(var source=Image.FromHbitmap(h))return new Bitmap(source);}catch{return null;}finally{if(h!=IntPtr.Zero)DeleteObject(h);Release(factory);}}
  public static Image Icon(DeskItem item){if(item==null)throw new ArgumentNullException("item");string custom=item.icon??"",target=item.target??"";string key=item.type+"|"+target+"|"+custom;try{if(File.Exists(custom))key+="|"+File.GetLastWriteTimeUtc(custom).Ticks;if(File.Exists(target))key+="|"+File.GetLastWriteTimeUtc(target).Ticks;}catch{}lock(gate){Image result;if(cache.TryGetValue(key,out result))return result;try{if(File.Exists(custom)){using(var source=Image.FromFile(custom))result=new Bitmap(source);}}catch{}if(result==null&&item.type!="url")result=ShellIcon(target);if(result==null){string name=item.type=="url"?"Browser":item.type=="app"?"Terminal":"Explorer";string asset=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MacDesk","Rainmeter","Skins","MacDesk","@Resources","Icons",name+".png");try{using(var source=Image.FromFile(asset))result=new Bitmap(source);}catch{}}if(result==null){var b=new Bitmap(96,96);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;g.Clear(Color.Transparent);using(var brush=new SolidBrush(Color.FromArgb(70,115,170)))g.FillEllipse(brush,4,4,88,88);using(var font=new Font("Segoe UI",34,FontStyle.Bold,GraphicsUnit.Pixel))using(var brush=new SolidBrush(Color.White))g.DrawString(item.type=="url"?"↗":"▣",font,brush,23,23);}result=b;}cache[key]=result;return result;}}
 }
